const worlds=[{id:'coding',cat:'codeCat',desc:'codingDesc',tags:['Python','C++','C#','Windows'],reward:'robot',bg:'#e9def5'},{id:'office',cat:'officeCat',desc:'officeDesc',tags:['Excel','Word','PowerPoint'],reward:'memory',bg:'#e1eaf4'},{id:'math',cat:'mathCat',desc:'mathDesc',tags:['functions','quadratics','Desmos'],reward:'block',bg:'#e7eddb'},{id:'typing',cat:'typeCat',desc:'typingDesc',tags:['speed','accuracy','rhythm'],reward:'train',bg:'#f5e8d6'}];
function render(){document.documentElement.lang=lang;document.title='LevelUp — '+t('dashboard');$$('[data-i]').forEach(e=>e.innerHTML=t(e.dataset.i));$('#language').value=lang;$('#close-modal').ariaLabel=t('close');$('.small-avatar').ariaLabel=t('achievements');$('.skip').textContent={en:'Skip to content',uz:'Asosiy qismga o‘tish',ru:'Перейти к содержимому'}[lang];$('#world-grid').innerHTML=worlds.map(w=>`<article class="world-card"><div class="card-art" style="background:${w.bg}"><span class="category">${t(w.cat)}</span>${drawings[w.id]}</div><div class="card-body"><h3>${t(w.id)}</h3><p>${t(w.desc)}</p><div class="tags">${w.tags.map(tag=>`<span>${copy.en[tag]?t(tag):tag}</span>`).join('')}</div><div class="reward"><span>♧</span> ${t('reward')} <b>${t(w.reward)}</b></div><button class="card-button" data-world="${w.id}"><span>${t('enter')}</span><span>↗</span></button></div></article>`).join('');$('.code-float span').textContent={en:'skill unlocked',uz:'yangi ko‘nikma',ru:'новый навык'}[lang];$('.art-caption').textContent=`${t('learn')} → ${t('play')} → LEVEL UP`;renderStats()}
let cleanup=()=>{},returnFocus=null;
const modal=$('#modal');
function show(kicker,html){cleanup();cleanup=()=>{};$('#modal-kicker').textContent=t(kicker);$('#modal-content').innerHTML=html;if(!modal.open){returnFocus=document.activeElement;modal.showModal()}modal.scrollTop=0}
function close(){cleanup();cleanup=()=>{};modal.close();returnFocus?.focus()}
$('#close-modal').onclick=close;modal.addEventListener('cancel',e=>{e.preventDefault();close()});modal.addEventListener('click',e=>{if(e.target===modal){const b=modal.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)close()}});
$('#language').onchange=e=>{lang=e.target.value;write('levelup-language',lang);if(modal.open)close();render()};
document.addEventListener('click',e=>{const world=e.target.closest('button[data-world]');if(world){openWorld(world.dataset.world);return}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='typing')openTyping();if(action==='quests')openQuests();if(action==='achievements')openAchievements();if(action==='arena')openArena()});
function openWorld(id){if(id==='typing')return openTyping();if(id==='coding')return codingLesson();if(id==='office')return officeLesson();if(id==='math')return mathLesson()}
function tabs(entries,current,callback){const row=$('.tab-row');if(!row)return;row.innerHTML=entries.map(([id,name])=>`<button class="${id===current?'selected':''}" data-tab="${id}" aria-pressed="${id===current}">${name}${state.completed.includes(`${row.dataset.world}-${id}`)?' ✓':''}</button>`).join('');row.querySelectorAll('button').forEach(b=>b.onclick=()=>callback(b.dataset.tab))}
function lessonShell(world,title,intro,html){show('lesson',`<h2 id="modal-title">${title}</h2><p>${intro}</p><div class="tab-row" data-world="${world}" aria-label="${t('choose')}"></div><div id="lesson-body">${html}</div><div id="unlock-area"></div>`);if(unlocked(world))rewardBar(world)}
function feedback(world,id,valid){const f=$('#feedback');f.className='feedback '+(valid?'success':'error');if(valid){f.textContent=award(id)?t('correct'):t('againCorrect');rewardBar(world)}else f.textContent=t('incorrect')}
function rewardBar(world){const area=$('#unlock-area');if(area){area.innerHTML=`<div class="unlocked"><span>✦ ${t('unlocked')}</span><button class="primary" id="reward-play">${t('openGame')} →</button></div>`;$('#reward-play').onclick=()=>({coding:openMaze,office:openMemory,math:openArena}[world])()}}
function answerForm(){return `<form class="answer-form" id="answer-form"><input id="answer" aria-label="${t('answer')}" placeholder="${t('answer')}" autocomplete="off" required maxlength="100"><button class="primary" type="submit">${t('check')} →</button></form><div id="feedback" class="feedback" role="status"></div>`}
function codingLesson(kind='python'){
const examples={python:{code:'score = 6\nbonus = 4\nprint(score + bonus)',answer:'10',hint:{en:'The + operator adds two numbers. 6 + 4 = ?',uz:'+ belgisi ikkita sonni qo‘shadi. 6 + 4 = ?',ru:'Оператор + складывает числа. 6 + 4 = ?'}},cpp:{code:'#include <iostream>\nint main() {\n  int gems = 3;\n  std::cout << gems * 4;\n}',answer:'12',hint:{en:'The * operator multiplies. There are 3 packs with 4 gems each.',uz:'* belgisi ko‘paytiradi. 3 ta qutining har birida 4 tadan kristall bor.',ru:'Оператор * умножает. В 3 наборах по 4 кристалла.'}},csharp:{code:'int energy = 20;\nenergy -= 5;\nConsole.WriteLine(energy);',answer:'15',hint:{en:'The -= operator subtracts from the current value. Start at 20, then subtract 5.',uz:'-= belgisi joriy qiymatdan ayiradi. 20 dan 5 ni ayir.',ru:'Оператор -= уменьшает текущее значение. Из 20 вычти 5.'}}};
const ex=examples[kind];const html=kind==='windows'?`<div class="lesson"><h3>${t('windowsPrompt')}</h3><p>${t('windowsHint')}</p><div class="option-grid">${['Windows + E','Ctrl + P','Alt + F4','Windows + L'].map(s=>`<button data-option="${s}">${s}</button>`).join('')}</div><div id="feedback" class="feedback" role="status"></div></div>`:`<div class="lesson"><div class="lesson-meta"><span>+50 XP</span><span>•</span><span>${t('lesson')} ${kind==='python'?'01':kind==='cpp'?'02':'03'}</span></div><h3 style="margin-top:12px">${t('codePrompt')}</h3><pre><code>${esc(ex.code)}</code></pre><p><b>${t('hint')}:</b> ${ex.hint[lang]}</p>${answerForm()}</div>`;
lessonShell('coding',t('coding'),t('codingDesc'),html);tabs([['python','Python'],['cpp','C++'],['csharp','C#'],['windows','Windows']],kind,codingLesson);if(kind==='windows')$$('[data-option]').forEach(b=>b.onclick=()=>feedback('coding','coding-windows',b.dataset.option==='Windows + E'));else $('#answer-form').onsubmit=e=>{e.preventDefault();feedback('coding','coding-'+kind,$('#answer').value.trim()===ex.answer)};
}
function officeLesson(kind='excel'){
const title=kind==='excel'?'officeExcel':kind==='word'?'wordTitle':'pptTitle';const intro=kind==='excel'?'excelIntro':kind==='word'?'wordIntro':'pptIntro';let content='';
if(kind==='excel')content=`<div class="progress-list"><div class="progress-item"><b>A1</b><span>12</span><b>A2</b><span>8</span><b>A3</b><span>5</span></div></div><h3>${t('excelQuestion')}</h3><p>${t('hint')}: ${t('excelHint')}</p>${answerForm()}`;
else {const options=kind==='word'?['normal','heading','caption','footnote']:['disappear','spin','fly','fadeOut'];content=`${kind==='ppt'?`<div class="slide-preview" id="slide"><span>${t('slideText')}</span></div><button class="text-button" id="preview">▶ ${t('preview')}</button>`:''}<h3 style="margin-top:20px">${t(kind==='word'?'wordQuestion':'pptQuestion')}</h3><div class="option-grid">${options.map(o=>`<button data-option="${o}">${t(o)}</button>`).join('')}</div><div id="feedback" class="feedback" role="status"></div>`}
lessonShell('office',t('office'),t('officeDesc'),`<div class="lesson"><h3>${t(title)}</h3><p>${t(intro)}</p>${content}</div>`);tabs([['excel','Excel'],['word','Word'],['ppt','PowerPoint']],kind,officeLesson);
if(kind==='excel')$('#answer-form').onsubmit=e=>{e.preventDefault();const v=$('#answer').value.replace(/\s/g,'').toUpperCase();feedback('office','office-excel',['=SUM(A1:A3)','=СУММ(A1:A3)','=A1+A2+A3','=SUM(A1,A2,A3)','=SUM(A1;A2;A3)'].includes(v))};else $$('[data-option]').forEach(b=>b.onclick=()=>feedback('office','office-'+kind,b.dataset.option===(kind==='word'?'heading':'fly')));
if(kind==='ppt')$('#preview').onclick=()=>{const s=$('#slide');s.classList.remove('animate');void s.offsetWidth;s.classList.add('animate')};
}
function mathLesson(kind='linear'){
const eq=kind==='linear'?'y = 2x + 3':'y = x² − 4',x=kind==='linear'?4:3,answer=kind==='linear'?11:5;
lessonShell('math',t('graphQuest'),t('mathDone'),`<div class="lesson"><div class="lesson-meta">+50 XP · ${t(kind)}</div><h3 style="margin-top:13px">${t('mathQuestion').replace('{equation}',eq).replace('{x}',x)}</h3><p>${t('mathHint')}</p><div class="graph-tools"><button class="mode-button" id="load-desmos">${t('loadDesmos')} ↗</button><a href="https://www.desmos.com/calculator?lang=${lang==='ru'?'ru':'en'}" target="_blank" rel="noopener">${t('externalGraph')}</a></div><p style="font-size:11px">${t('desmosNote')}</p><div id="graph"></div>${answerForm()}</div>`);tabs([['linear',t('linear')],['quadratic',t('quadratic')]],kind,mathLesson);
$('#answer').inputMode='decimal';$('#answer-form').onsubmit=e=>{e.preventDefault();const value=$('#answer').value.trim().replace(',','.');feedback('math','math-'+kind,value!==''&&Number(value)===answer)};
$('#load-desmos').onclick=()=>{$('#graph').innerHTML=`<div class="graph-wrap"><iframe src="https://www.desmos.com/calculator?lang=${lang==='ru'?'ru':'en'}" title="Desmos" loading="lazy" referrerpolicy="strict-origin-when-cross-origin"></iframe></div>`;$('#load-desmos').disabled=true};
}
function openQuests(){show('progress',`<h2 id="modal-title">${t('questTitle')}</h2><p>${t('noQuests')}</p><div class="progress-list">${worlds.map(w=>{const n=state.completed.filter(x=>x.startsWith(w.id+'-')).length,total=allowedQuestIds.filter(x=>x.startsWith(w.id+'-')).length;return `<div class="progress-item"><b>${t(w.id)}</b><span>${n}/${total} ${t('completed')}</span><button data-world="${w.id}">${t('enter')} →</button></div>`}).join('')}</div><p class="notice">${t(storageWorks?'saved':'storageFail')}</p>`)}
function openAchievements(){show('achievements',`<h2 id="modal-title">${t('badges')}</h2><p>${t('badgeNote')}</p><div class="game-stats"><span>✦ ${state.completed.length*50} XP</span><span>${state.completed.length} / ${allowedQuestIds.length} ${t('completed')}</span></div><div class="badge-grid">${[['coding','⌘','firstCode'],['office','▦','toolHero'],['math','◇','mathHero'],['typing','🚂','typeHero']].map(([id,icon,key])=>`<div class="badge ${unlocked(id)?'earned':''}"><span>${icon}</span><b>${t(key)} ${unlocked(id)?'✓':''}</b></div>`).join('')}</div><p class="notice">${t(storageWorks?'saved':'storageFail')}</p>`)}
function dpad(id=''){return `<div class="dpad" data-pad="${id}"><button data-dir="0,-1" aria-label="↑">↑</button><button data-dir="-1,0" aria-label="←">←</button><button data-dir="0,1" aria-label="↓">↓</button><button data-dir="1,0" aria-label="→">→</button></div>`}
function gameGate(world){if(unlocked(world))return true;openWorld(world);return false}
function openMaze(){if(!gameGate('coding'))return;show('robot',`<h2 id="modal-title">${t('robot')}</h2><p>${t('mazeHelp')}</p><div class="game-stats"><span>${t('move')}: <b id="moves">0</b></span></div><div class="maze" aria-label="${t('robot')}"></div>${dpad()}<div id="feedback" class="feedback" role="status"></div><div class="game-buttons"><button id="restart-maze" class="primary">${t('restart')}</button><button class="mode-button" data-world="coding">${t('back')}</button></div>`);const walls=new Set([2,8,10,12,14,16,20,22,25,26,28]);let pos=0,moves=0,won=false;function draw(){$('.maze').innerHTML=Array.from({length:36},(_,i)=>`<div class="maze-cell ${walls.has(i)?'wall':''}">${i===pos?'🤖':i===35?'⚑':''}</div>`).join('');$('#moves').textContent=moves}function move(dx,dy){if(won)return;const x=pos%6+dx,y=Math.floor(pos/6)+dy,next=y*6+x;if(x<0||x>5||y<0||y>5||walls.has(next))return;pos=next;moves++;draw();if(pos===35){won=true;$('#feedback').className='feedback success';$('#feedback').textContent=t('mazeWin')}}$$('[data-dir]').forEach(b=>b.onclick=()=>move(...b.dataset.dir.split(',').map(Number)));const key=e=>{const dir={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]}[e.key];if(dir){e.preventDefault();move(...dir)}};document.addEventListener('keydown',key);cleanup=()=>document.removeEventListener('keydown',key);$('#restart-maze').onclick=openMaze;draw()}
function shuffle(items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function openMemory(){if(!gameGate('office'))return;show('memory',`<h2 id="modal-title">${t('memory')}</h2><p>${t('memoryHelp')}</p><div class="memory"></div><div id="feedback" class="feedback" role="status"></div><div class="game-buttons"><button id="restart-memory" class="primary">${t('restart')}</button><button class="mode-button" data-world="office">${t('back')}</button></div>`);const pairs=[['Ctrl + C','copy'],['Ctrl + V','paste'],['Ctrl + S','save'],['Ctrl + Z','undo']],cards=shuffle(pairs.flatMap(([key,label],id)=>[{id,text:key},{id,text:t(label)}]));let selected=[],matched=new Set(),busy=false,timer;function draw(){$('.memory').innerHTML=cards.map((c,i)=>`<button data-card="${i}" class="${matched.has(c.id)?'matched':selected.includes(i)?'revealed':''}" ${matched.has(c.id)?'disabled':''} aria-label="${matched.has(c.id)||selected.includes(i)?esc(c.text):String(i+1)}">${matched.has(c.id)||selected.includes(i)?esc(c.text):'?'}</button>`).join('');$$('[data-card]').forEach(b=>b.onclick=()=>flip(Number(b.dataset.card)))}function flip(i){if(busy||selected.includes(i)||matched.has(cards[i].id))return;selected.push(i);draw();if(selected.length===2){busy=true;timer=setTimeout(()=>{if(cards[selected[0]].id===cards[selected[1]].id)matched.add(cards[i].id);selected=[];busy=false;draw();if(matched.size===4){$('#feedback').className='feedback success';$('#feedback').textContent=t('memoryWin')}},750)}}cleanup=()=>clearTimeout(timer);$('#restart-memory').onclick=openMemory;draw()}
const wordLists={en:['code','train','learn','build','dream','pixel','bright','quest','robot','world','power','skill','green','level','school','magic','future','create','focus','explore'],uz:['kod','bilim','maktab','kitob','qalam','orzular','dunyo','yulduz','kelajak','dars','robot','maydon','poyezd','tezlik','g‘alaba','o‘yin','o‘rgan','do‘st','maqsad','yangi'],ru:['код','поезд','урок','школа','мир','робот','знание','мечта','игра','путь','цель','слово','книга','вперёд','успех','сила','ритм','город','навык','друг']};
function normalizeWord(s){return s.trim().toLocaleLowerCase().replace(/[‘’ʻʼ`]/g,"'")}
function openTyping(){show('train',`<h2 id="modal-title">${t('train')}</h2><p>${t('typeHelp')}</p><div class="game-stats"><span>${t('time')}: <b id="time">45</b>s</span><span>${t('deliveries')}: <b id="deliveries">0</b></span><span>${t('wpm')}: <b id="wpm">0</b></span><span>${t('accuracy')}: <b id="accuracy">—</b></span></div><div class="train-stage"><div class="word-target" id="word">${t('typeReady')}</div><div class="train" aria-hidden="true">🚂</div></div><input class="typing-input" id="typing-input" aria-label="${t('typeWord')}" placeholder="${t('typeWord')}" disabled autocomplete="off" autocapitalize="off" spellcheck="false"><div id="feedback" class="feedback" role="status">${t('typeReward')}</div><div class="game-buttons"><button class="primary" id="start-run">${t('startRun')}</button></div>`);let timer,deadline,start,active=false,delivered=0,correctChars=0,attemptedChars=0,words=shuffle(wordLists[lang]),idx=0;const input=$('#typing-input');let wrongTyped=0;function current(){return words[idx%words.length]}function drawWord(){$('#word').textContent=current();$('.train').style.left=(8+(delivered%12)*6)+'%'}function stats(){const elapsed=Math.max(1,(Date.now()-start)/1000);$('#deliveries').textContent=delivered;$('#wpm').textContent=Math.round(correctChars/5/(elapsed/60));$('#accuracy').textContent=attemptedChars?Math.round(correctChars/attemptedChars*100)+'%':'—'}function end(){active=false;clearInterval(timer);input.disabled=true;$('#word').textContent=t('typeEnd');$('#time').textContent='0';$('#start-run').disabled=false;$('#start-run').textContent=t('restart');stats();$('#feedback').className='feedback '+(delivered>=5?'success':'');$('#feedback').textContent=delivered>=5?(award('typing-run')?t('correct'):t('againCorrect')):t('typeLow')}
function tick(){const left=Math.max(0,Math.ceil((deadline-Date.now())/1000));$('#time').textContent=left;if(left===0)end()}
$('#start-run').onclick=()=>{clearInterval(timer);active=true;delivered=0;correctChars=0;attemptedChars=0;wrongTyped=0;idx=0;words=shuffle(wordLists[lang]);start=Date.now();deadline=start+45000;input.disabled=false;input.value='';input.focus();$('#start-run').disabled=true;$('#feedback').className='feedback';$('#feedback').textContent=t('typeReward');drawWord();stats();tick();timer=setInterval(tick,200)};
input.addEventListener('paste',e=>e.preventDefault());input.addEventListener('drop',e=>e.preventDefault());
input.addEventListener('beforeinput',e=>{if(e.inputType==='insertFromPaste'||e.inputType==='insertFromDrop'){e.preventDefault();return}if(active&&e.data&&e.data!==' '){const pos=input.selectionStart;const expected=normalizeWord(current()).slice(pos,pos+e.data.length);if(normalizeWord(e.data)!==expected)wrongTyped+=e.data.length}});
input.addEventListener('keydown',e=>{if(!active||e.isComposing||!['Enter',' '].includes(e.key))return;e.preventDefault();if(Date.now()>=deadline){end();return}const val=normalizeWord(input.value);if(!val)return;const good=val===normalizeWord(current());attemptedChars+=good?current().length+wrongTyped:Math.max(val.length,current().length)+wrongTyped;wrongTyped=0;if(good){delivered++;correctChars+=current().length;idx++;input.value='';$('#feedback').textContent='✓ '+t('deliveries')+': '+delivered;$('#feedback').className='feedback success';drawWord()}else{$('#feedback').className='feedback error';$('#feedback').textContent=t('incorrect');input.select()}stats()});cleanup=()=>{active=false;clearInterval(timer)};
}
function openArena(){if(!unlocked('math')){show('arena',`<h2 id="modal-title">${t('block')}</h2><p>${t('locked')}</p><div class="game-buttons"><button class="primary" data-world="math">${t('goMath')} →</button></div><p class="notice">${t('arenaNote')}</p>`);return}show('arena',`<h2 id="modal-title">${t('arenaTitle')}</h2><p>${t('arenaHelp')}</p><div class="tab-row"><button class="selected" id="mode-bot">${t('bot')}</button><button id="mode-friend">${t('friend')}</button></div><div class="arena-score"><span>${t('purple')}: <b id="score1">0</b></span><span>${t('orange')}: <b id="score2">0</b></span></div><div class="arena-field" role="img" aria-label="${t('block')}"></div><div class="game-buttons">${dpad('p1')}<div id="p2-pad" hidden>${dpad('p2')}</div></div><div id="feedback" class="feedback" role="status">${t('roundReady')}</div><div class="game-buttons"><button class="primary" id="start-arena">${t('playRound')}</button></div><p class="notice">${t('arenaNote')}</p>`);
const walls=new Set([14,15,20,21,26,32,38,39,44,45,50,56,62,63,68,69]);let mode='bot',positions=[0,83],scores=[0,0],gem=41,active=false,timer,lastMoves=[0,0];
function draw(){$('.arena-field').innerHTML=Array.from({length:84},(_,i)=>`<div class="arena-cell ${walls.has(i)?'block':i===positions[0]?'p1':i===positions[1]?'p2':i===gem?'gem':''}">${i===positions[0]?'▣':i===positions[1]?'▣':i===gem?'◆':''}</div>`).join('');$('#score1').textContent=scores[0];$('#score2').textContent=scores[1]}
function spawnGem(){const free=Array.from({length:84},(_,i)=>i).filter(i=>!walls.has(i)&&!positions.includes(i));gem=free[Math.floor(Math.random()*free.length)]}
function move(player,dx,dy){if(!active)return;const now=Date.now();if(now-lastMoves[player]<95)return;lastMoves[player]=now;const x=positions[player]%12+dx,y=Math.floor(positions[player]/12)+dy,n=y*12+x;if(x<0||x>11||y<0||y>6||walls.has(n)||positions[1-player]===n)return;positions[player]=n;if(n===gem){scores[player]++;if(scores[player]>=5){active=false;clearInterval(timer);$('#feedback').className='feedback success';$('#feedback').textContent=`${t(player?'orange':'purple')} ${t('wins')}`;$('#start-arena').disabled=false;$('#start-arena').textContent=t('restart')}else spawnGem()}draw()}
function botStep(){if(!active)return;const queue=[[positions[1],[]]],seen=new Set([positions[1]]);while(queue.length){const [pos,path]=queue.shift();if(pos===gem&&path.length){move(1,...path[0]);return}for(const dir of [[1,0],[-1,0],[0,1],[0,-1]]){const x=pos%12+dir[0],y=Math.floor(pos/12)+dir[1],next=y*12+x;if(x>=0&&x<12&&y>=0&&y<7&&!walls.has(next)&&next!==positions[0]&&!seen.has(next)){seen.add(next);queue.push([next,[...path,dir]])}}}}
function setMode(value){mode=value;active=false;clearInterval(timer);$('#mode-bot').classList.toggle('selected',value==='bot');$('#mode-friend').classList.toggle('selected',value==='friend');$('#p2-pad').hidden=value==='bot';$('#start-arena').disabled=false;$('#feedback').textContent=t('roundReady');positions=[0,83];scores=[0,0];draw()}
$('#mode-bot').onclick=()=>setMode('bot');$('#mode-friend').onclick=()=>setMode('friend');$('#start-arena').onclick=()=>{clearInterval(timer);positions=[0,83];scores=[0,0];active=true;lastMoves=[0,0];spawnGem();draw();$('#feedback').className='feedback';$('#feedback').textContent=t('playing');$('#start-arena').disabled=true;if(mode==='bot')timer=setInterval(botStep,420)};
$$('[data-pad]').forEach(pad=>pad.querySelectorAll('button').forEach(b=>b.onclick=()=>move(pad.dataset.pad==='p2'?1:0,...b.dataset.dir.split(',').map(Number))));
const key=e=>{const dirs={w:[0,-1],a:[-1,0],s:[0,1],d:[1,0],ц:[0,-1],ф:[-1,0],ы:[0,1],в:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]};const k=e.key.startsWith('Arrow')?e.key:e.key.toLowerCase();if(dirs[k]){e.preventDefault();const player=k.startsWith('Arrow')&&mode==='friend'?1:0;move(player,...dirs[k])}};document.addEventListener('keydown',key);cleanup=()=>{clearInterval(timer);document.removeEventListener('keydown',key)};draw();
}
render();
